import java.util.Scanner;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[] sorted = {n, m};
        if (sorted[0] > sorted[1]) {
            int temp = sorted[0];
            sorted[0] = sorted[1];
            sorted[1] = temp;
        }
        n = sorted[0];
        m = sorted[1];

        Map<Integer, Integer> nestedMap = Map.of(
            2, 2,
            3, 1,
            7, 1
        );

        int value = 0;
        if (m > 1 && m < 6 && m > 1 && m < 5) {
            value = 1;
        }
        int nestedValue = nestedMap.getOrDefault(m, 0);
        int result = (~1 & n * m - 2 * (value < nestedValue ? 1 : 0));
        System.out.println(result);
        scanner.close();
    }
}
